func zip<A, B, E>(_ a: Result<A, E>, _ b: Result<B, E>) -> Result<(A, B), E> {
    switch (a, b) {
    case let (.success(x), .success(y)): return .success((x, y))
    case let (.failure(e), _): return .failure(e)
    case let (_, .failure(e)): return .failure(e)
    }
